var isCovered = function(ranges, left, right) {
    const diff = Array(52).fill(0);
    for (const [l, r] of ranges) {
        diff[l]++;
        diff[r + 1]--;
    }
    let curr = 0;
    for (let i = 1; i <= 50; ++i) {
        curr += diff[i];
        if (i >= left && i <= right && curr <= 0) return false;
    }
    return true;
};
